import{_ as l,o as a,c as e,a2 as t}from"./chunks/framework.BbQrW5_t.js";const p=JSON.parse('{"title":"初级篇·筑基","description":"","frontmatter":{"title":"初级篇·筑基","date":"2026-09-03T00:00:00.000Z"},"headers":[],"relativePath":"study/cyber-security/01-初级篇-筑基.md","filePath":"study/cyber-security/01-初级篇-筑基.md","lastUpdated":null}'),r={name:"study/cyber-security/01-初级篇-筑基.md"};function o(s,i,n,u,h,c){return a(),e("div",null,[...i[0]||(i[0]=[t('<h1 id="🧱-初级篇-·-筑基-第-1-年" tabindex="-1">🧱 初级篇 · 筑基（第 1 年） <a class="header-anchor" href="#🧱-初级篇-·-筑基-第-1-年" aria-label="Permalink to &quot;🧱 初级篇 · 筑基（第 1 年）&quot;">​</a></h1><blockquote><p>目标：建立&quot;网络→系统→Web→攻击面&quot;的完整地图，拿下 NISP，CTF 能上手。</p></blockquote><h2 id="模块-1-网络协议-工程师速通版" tabindex="-1">模块 1：网络协议（工程师速通版） <a class="header-anchor" href="#模块-1-网络协议-工程师速通版" aria-label="Permalink to &quot;模块 1：网络协议（工程师速通版）&quot;">​</a></h2><p>你不缺编程，缺的是<strong>包级别</strong>的视野：</p><ul><li>TCP/IP 分层、三次握手/四次挥手——用 Wireshark <strong>抓自己的流量</strong>看，别背书</li><li>HTTP/1.1 vs HTTP/2 vs HTTPS：TLS 握手过程、证书链（抓包对比明文/密文）</li><li>DNS 解析全链路、CDN 与子域名的关系（后面子域名枚举的原理基础）</li><li>代理/VPN/NAT：流量如何被改写——Burp 挂代理后就懂了</li><li>📚 资源：《图解 TCP/IP》、Wireshark 官方示例抓包文件</li></ul><h2 id="模块-2-linux-与命令行" tabindex="-1">模块 2：Linux 与命令行 <a class="header-anchor" href="#模块-2-linux-与命令行" aria-label="Permalink to &quot;模块 2：Linux 与命令行&quot;">​</a></h2><ul><li>文件系统/权限位/SUID、用户与进程、systemd</li><li>bash 管道哲学：grep/awk/sed 组合出迷你分析器</li><li>安全工具位：nmap、curl、netcat、sqlmap 先会&quot;用&quot;</li><li>📚 资源：OverTheWire Bandit（游戏化练命令行，强推）</li></ul><h2 id="模块-3-web-安全基础-owasp-top-10" tabindex="-1">模块 3：Web 安全基础（OWASP Top 10） <a class="header-anchor" href="#模块-3-web-安全基础-owasp-top-10" aria-label="Permalink to &quot;模块 3：Web 安全基础（OWASP Top 10）&quot;">​</a></h2><p>每类漏洞按「原理 → 手工利用 → DVWA 复现 → 修复视角」四步走：</p><ol><li>SQL 注入（联合/布尔/时间盲注，手工优于 sqlmap 先行）</li><li>XSS（反射/存储/DOM）、CSRF</li><li>文件上传/文件包含、SSRF</li><li>反序列化（概念）、认证与会话缺陷</li></ol><ul><li>🔧 工具：Burp Suite Community——安全人的手术刀</li><li>📚 资源：《Web 安全深度剖析》、DVWA、PortSwigger Web Security Academy（免费，质量极高）</li></ul><h2 id="模块-4-python-安全编程-你的超车道" tabindex="-1">模块 4：Python 安全编程（你的超车道） <a class="header-anchor" href="#模块-4-python-安全编程-你的超车道" aria-label="Permalink to &quot;模块 4：Python 安全编程（你的超车道）&quot;">​</a></h2><ul><li>socket 端口扫描器（50 行）→ requests 目录爆破 → 子域名枚举</li><li>异步并发（asyncio）把扫描器提速 50 倍</li><li>PoC/EXP 的工程规范：参数化、日志、退出码——工程师写安全代码，降维打击</li></ul><h2 id="模块-5-操作系统与内网概念" tabindex="-1">模块 5：操作系统与内网概念 <a class="header-anchor" href="#模块-5-操作系统与内网概念" aria-label="Permalink to &quot;模块 5：操作系统与内网概念&quot;">​</a></h2><ul><li>Windows 域基础概念：域控/Kerberos/组策略（第 2 年内网渗透的地基）</li><li>Linux 提权思路清单（SUID/cron/Capabilities）</li><li>密码的存储、散列与破解概念（hashcat 认识一下）</li></ul><h2 id="模块-6-ctf-入门" tabindex="-1">模块 6：CTF 入门 <a class="header-anchor" href="#模块-6-ctf-入门" aria-label="Permalink to &quot;模块 6：CTF 入门&quot;">​</a></h2><ul><li>题型地图：Web/Misc/Crypto/Reverse/Pwn——前三是主战场</li><li>平台：攻防世界（新手区→进阶区）、Bugku、PicoCTF</li><li>🎯 目标：独立解出 20 道 Web 题 + 10 道 Misc</li></ul><h2 id="✅-年度验收标准" tabindex="-1">✅ 年度验收标准 <a class="header-anchor" href="#✅-年度验收标准" aria-label="Permalink to &quot;✅ 年度验收标准&quot;">​</a></h2><ul><li>[ ] Wireshark 能独立分析一次完整 TLS 会话</li><li>[ ] DVWA 全关卡 Medium 难度手工通关</li><li>[ ] 3 个自研 Python 安全小工具入库</li><li>[ ] NISP 证书到手</li><li>[ ] CTF 累计 30 题</li></ul>',19)])])}const b=l(r,[["render",o]]);export{p as __pageData,b as default};
